// Charts in the document view: a chart of a Word document is drawn in its
// frame from the values its part cached, scales with the zoom, is on the
// printed page, stays a placeholder when its part cannot be read, and leaves
// the file as it was.
//
// No screenshots: the pixels of the canvas of a page are read with
// getImageData(). Every document is generated by code. The sample pages are
// 600 x 400 px with margins of 40 px; each chart has one series of three
// columns (50, 100, 25 on an axis from 0 to 100) filled with one plain colour.
import type { Page } from '@playwright/test';
import { catAx, chartXml, group, legend, numRef, ser, strRef, valAx } from '../test/chart-fixtures';
import { p, r, tbl, tc, tr, words } from '../test/doc-layout-fixtures';
import { chartParts, columnsChart, floatingChart, inlineChart, partRels } from '../test/docx-chart-fixtures';
import { ZipArchive } from '../src/zip';
import { docSection, docx, textBoxRun } from './fixtures/docx';
import { expect, expectResponsive, test } from './helpers';

const GREEN = [0, 176, 80];
const RED = [192, 0, 0];
const BLUE = [0, 112, 192];
const PLACEHOLDER = [241, 243, 244];
/** The size of the frame of the chart that stands alone in the first line of the page, px of the page. */
const FRAME = { width: 300, height: 200 };
interface Box {
  x: number;
  y: number;
  width: number;
  height: number;
}

function once<T>(make: () => Promise<T>): () => Promise<T> {
  let value: Promise<T> | undefined;
  return () => (value ??= make());
}

const chartDoc = once(async () => docx(p(inlineChart('rIdC1', FRAME.width, FRAME.height)) + p('Below the chart'), await chartParts([{ rel: 'rIdC1', xml: columnsChart() }])));
const brokenDoc = once(async () => docx(p(inlineChart('rIdC1', FRAME.width, FRAME.height)) + p('Below the chart'), await chartParts([{ rel: 'rIdC1', xml: '<c:chartSpace><c:chart>' }])));

async function mountDoc(page: Page, bytes: Uint8Array, zoom = 1): Promise<void> {
  await page.goto('/e2e/pages/doc.html');
  await expect(page.locator('#state')).toHaveText('ready');
  await page.evaluate(([input, opts]) => (window as any).__mountDoc(input, opts), [Array.from(bytes), { zoom }] as [number[], object]);
  await page.waitForFunction(() => (window as any).__docView.layoutDone === true, undefined, { timeout: 60_000 });
  await settled(page);
}

/** Lets the view bring the screen up to date: its updates run in animation frames. */
const settled = (page: Page) => page.evaluate(() => new Promise<void>((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve()))));

interface Found {
  /** Pixels of the colour, and their bounding box, in px of the page. */
  count: number;
  x: number;
  y: number;
  width: number;
  height: number;
  /** The height of each run of neighbouring pixel columns that hold the colour, px of the page: one per column of the chart. */
  runs: number[];
  /** Canvas pixels per px of the page. */
  scale: number;
}

/** Looks for a colour in a canvas or a picture of a page that is `pageWidth` px wide. In the page: no closure. */
function findColour(args: { source: 'canvas' | 'print'; index: number; colour: number[]; pageWidth: number; exact?: boolean }): Found {
  let canvas: HTMLCanvasElement;
  if (args.source === 'canvas') {
    const found = document.querySelector(`#host .bym-doc-page[data-page="${args.index + 1}"] canvas`) as HTMLCanvasElement | null;
    if (!found) throw new Error(`page ${args.index + 1} has no canvas`);
    canvas = found;
  } else {
    const image = document.querySelectorAll('.bym-print img')[args.index] as HTMLImageElement | undefined;
    if (!image) throw new Error(`no printed page ${args.index + 1}`);
    canvas = document.createElement('canvas');
    canvas.width = image.naturalWidth;
    canvas.height = image.naturalHeight;
    canvas.getContext('2d')!.drawImage(image, 0, 0);
  }
  const data = canvas.getContext('2d')!.getImageData(0, 0, canvas.width, canvas.height).data;
  const scale = canvas.width / args.pageWidth;
  const [red, green, blue] = args.colour;
  // Edges are smoothed: a colour of a series is taken with a little room, the grey of a placeholder exactly (charts have light greys of their own).
  const room = args.exact ? 0 : 6;
  let count = 0;
  let left = Infinity;
  let top = Infinity;
  let right = -1;
  let bottom = -1;
  const perColumn = new Array<number>(canvas.width).fill(0);
  for (let y = 0; y < canvas.height; y++) {
    for (let x = 0; x < canvas.width; x++) {
      const i = (y * canvas.width + x) * 4;
      if (Math.abs(data[i] - red) > room || Math.abs(data[i + 1] - green) > room || Math.abs(data[i + 2] - blue) > room) continue;
      count++;
      perColumn[x]++;
      if (x < left) left = x;
      if (x > right) right = x;
      if (y < top) top = y;
      if (y > bottom) bottom = y;
    }
  }
  const runs: number[] = [];
  let open = 0;
  for (let x = 0; x <= canvas.width; x++) {
    const here = x < canvas.width ? perColumn[x] : 0;
    if (here > 0) open = Math.max(open, here);
    else if (open > 0) {
      runs.push(open / scale);
      open = 0;
    }
  }
  if (count === 0) return { count, x: 0, y: 0, width: 0, height: 0, runs, scale };
  return { count, x: left / scale, y: top / scale, width: (right - left + 1) / scale, height: (bottom - top + 1) / scale, runs, scale };
}

const onPage = (page: Page, colour: number[], index = 0, pageWidth = 600) => page.evaluate(findColour, { source: 'canvas' as const, index, colour, pageWidth, exact: colour === PLACEHOLDER });

/**
 * Where the frame of the chart of chartDoc() stands on its page: the box of the placeholder the same
 * document shows when its chart part cannot be read. The layout of the two is the same (a unit test says so).
 */
async function frameOnPage(page: Page): Promise<Box> {
  await mountDoc(page, await brokenDoc());
  const grey = await onPage(page, PLACEHOLDER);
  expect(Math.abs(grey.width - FRAME.width), 'the placeholder is as wide as the frame').toBeLessThan(2.5);
  expect(Math.abs(grey.height - FRAME.height), 'the placeholder is as high as the frame').toBeLessThan(2.5);
  return { x: grey.x, y: grey.y, width: grey.width, height: grey.height };
}

function expectInFrame(found: Found, frame: Box): void {
  expect(found.count, 'pixels of the colour of the series').toBeGreaterThan(200);
  expect(found.x).toBeGreaterThanOrEqual(frame.x - 1);
  expect(found.y).toBeGreaterThanOrEqual(frame.y - 1);
  expect(found.x + found.width).toBeLessThanOrEqual(frame.x + frame.width + 1);
  expect(found.y + found.height).toBeLessThanOrEqual(frame.y + frame.height + 1);
}

function expectColumns(found: Found): void {
  expect(found.runs.length, 'three columns').toBe(3);
  expect(found.runs[0] / found.runs[1]).toBeGreaterThan(0.45);
  expect(found.runs[0] / found.runs[1]).toBeLessThan(0.55);
  expect(found.runs[2] / found.runs[1]).toBeGreaterThan(0.2);
  expect(found.runs[2] / found.runs[1]).toBeLessThan(0.3);
}

test.describe('charts of a document', () => {
  test('a chart is drawn in its frame from the cached values', async ({ page }) => {
    const frame = await frameOnPage(page);
    await mountDoc(page, await chartDoc());
    const green = await onPage(page, GREEN);
    expectInFrame(green, frame);
    expectColumns(green);
    // The columns fill a good part of the frame: the tallest is most of its height.
    expect(green.runs[1]).toBeGreaterThan(FRAME.height * 0.5);
    expect((await onPage(page, PLACEHOLDER)).count, 'no placeholder').toBe(0);
    await expectResponsive(page);
  });

  test('the chart scales with the zoom', async ({ page }) => {
    const frame = await frameOnPage(page);
    // From half size to full size: a phone does not paint a page much finer than that.
    await mountDoc(page, await chartDoc(), 0.5);
    const before = await onPage(page, GREEN);
    expectColumns(before);
    await page.evaluate(() => (window as any).__docView.setZoom(1));
    await settled(page);
    await expect.poll(async () => (await onPage(page, GREEN)).scale / before.scale, { message: 'the canvas is twice as fine' }).toBeCloseTo(2, 1);
    const after = await onPage(page, GREEN);
    // In px of the page the chart is where it was; in pixels of the canvas it is twice as large each way.
    expectInFrame(after, frame);
    expectColumns(after);
    expect(Math.abs(after.x - before.x)).toBeLessThan(2);
    expect(Math.abs(after.width - before.width)).toBeLessThan(3);
    expect(after.count / before.count).toBeGreaterThan(3.4);
    expect(after.count / before.count).toBeLessThan(4.6);
  });

  test('charts beside text, in a table and in the header are drawn', async ({ page }) => {
    const charts = await chartParts([
      { rel: 'rIdC1', xml: columnsChart() },
      { rel: 'rIdC2', xml: columnsChart({ color: 'C00000' }) },
      { rel: 'rIdH1', xml: columnsChart({ color: '0070C0' }) },
    ]);
    const body =
      p(floatingChart('rIdC1', 300, 0, 200, 120) + r(words(30))) +
      tbl(tr(tc(p(inlineChart('rIdC2', 120, 90)))), [3000]) +
      docSection('<w:headerReference w:type="default" r:id="rIdH"/>').replace('w:top="600"', 'w:top="1500"');
    const bytes = await docx('', {
      body,
      headers: { rIdH: p(inlineChart('rIdC1', 80, 60)) },
      rels: charts.rels,
      parts: charts.parts.concat([partRels('header1.xml', [['rIdC1', 'chart', 'charts/chart3.xml']])]),
    });
    await mountDoc(page, bytes);
    const green = await onPage(page, GREEN);
    const red = await onPage(page, RED);
    const blue = await onPage(page, BLUE);
    // The chart beside the text: 300 px into the column, at the top of the body (margin 100 px).
    expectInFrame(green, { x: 340, y: 100, width: 200, height: 120 });
    expectColumns(green);
    // The chart of the table stands below the paragraph, at the left.
    expect(red.count, 'the chart in the table').toBeGreaterThan(100);
    expect(red.runs.length).toBe(3);
    expect(red.y).toBeGreaterThan(100);
    expect(red.x + red.width).toBeLessThan(340);
    // The chart of the header stands above the body.
    expect(blue.count, 'the chart in the header').toBeGreaterThan(50);
    expect(blue.runs.length).toBe(3);
    expect(blue.y + blue.height).toBeLessThan(100);
    expect((await onPage(page, PLACEHOLDER)).count, 'no placeholder').toBe(0);
  });

  test('charts in a footnote and in a text box are painted', async ({ page }) => {
    const charts = await chartParts([
      { rel: 'unused', xml: columnsChart({ color: 'C00000' }) },
      { rel: 'rIdC2', xml: columnsChart({ color: '0070C0' }) },
    ]);
    const bytes = await docx(p(r('Text with a note') + '<w:r><w:footnoteReference w:id="2"/></w:r>') + p(textBoxRun(250, 20, 240, 160, p(inlineChart('rIdC2', 200, 120)))), {
      footnotes: `<w:footnote w:id="2">${p(inlineChart('rIdN', 150, 90))}</w:footnote>`,
      rels: charts.rels,
      parts: charts.parts.concat([partRels('footnotes.xml', [['rIdN', 'chart', 'charts/chart1.xml']])]),
    });
    await mountDoc(page, bytes);
    const red = await onPage(page, RED);
    const blue = await onPage(page, BLUE);
    // The chart of the footnote stands at the foot of the page (400 px high, 40 px of margin).
    expect(red.count, 'the chart in the footnote').toBeGreaterThan(100);
    expectColumns(red);
    expect(red.y).toBeGreaterThan(200);
    expect(red.y + red.height).toBeLessThanOrEqual(361);
    // The chart of the text box stands inside the box: 250 px into the column, 20 px below the paragraph.
    expect(blue.count, 'the chart in the text box').toBeGreaterThan(100);
    expectColumns(blue);
    expectInFrame(blue, { x: 290, y: 60, width: 240, height: 160 });
    expect((await onPage(page, PLACEHOLDER)).count, 'no placeholder').toBe(0);
  });

  test('the language of the view is that of the numbers and of the made-up names of series', async ({ page }) => {
    const plot =
      group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', ser(0, { cat: strRef('Sheet1!$A$2:$A$4', ['a', 'b', 'c']), val: numRef('Sheet1!$B$2:$B$4', [0.5, 1.5, 2.5]) })) + catAx() + valAx();
    const bytes = await docx(p(inlineChart('rIdC1', 400, 260)), await chartParts([{ rel: 'rIdC1', xml: chartXml({ plot, tail: legend('r') }) }]));
    await page.goto('/e2e/pages/doc.html');
    await expect(page.locator('#state')).toHaveText('ready');
    // The words that reach a canvas: a chart writes its numbers and names with fillText() and nothing else.
    await page.evaluate(() => {
      const w = window as any;
      w.__words = [] as string[];
      const fillText = CanvasRenderingContext2D.prototype.fillText;
      CanvasRenderingContext2D.prototype.fillText = function (this: CanvasRenderingContext2D, text: string, ...rest: any[]) {
        w.__words.push(String(text));
        return (fillText as any).call(this, text, ...rest);
      };
    });
    const words = () => page.evaluate(() => ((window as any).__words as string[]).slice());
    await page.evaluate(([input]) => (window as any).__mountDoc(input, { zoom: 1, locale: 'en' }), [Array.from(bytes)]);
    await page.waitForFunction(() => (window as any).__docView.layoutDone === true, undefined, { timeout: 60_000 });
    await settled(page);
    const english = await words();
    expect(english).toContain('Series1');
    expect(english.some((text) => /^\d\.5$/.test(text)), `a tick with a decimal point in ${JSON.stringify(english)}`).toBe(true);
    await page.evaluate(() => {
      (window as any).__words.length = 0;
      (window as any).__docView.setLocale('tr');
    });
    await settled(page);
    await expect.poll(words, { message: 'the chart is painted again in Turkish' }).toContain('Seri1');
    const turkish = await words();
    expect(turkish.some((text) => /^\d,5$/.test(text)), `a tick with a decimal comma in ${JSON.stringify(turkish)}`).toBe(true);
    expect(turkish).not.toContain('Series1');
    expect(turkish.some((text) => /^\d\.5$/.test(text))).toBe(false);
  });

  test('laying the pages out anew, and a font table that changed, lay the charts out anew', async ({ page }) => {
    await mountDoc(page, await chartDoc());
    const state = () => page.evaluate(() => (window as any).__docView.getChartState() as { charts: number; layouts: number; values: number });
    const before = await state();
    expect(before.charts).toBe(1);
    expect(before.layouts).toBe(1);
    // Painting again, at another zoom, lays nothing out again.
    await page.evaluate(() => (window as any).__docView.setZoom(1.25));
    await settled(page);
    expect((await state()).layouts).toBe(1);
    // relayout(): what the host calls when it added fonts to the page by itself. The words of a chart may measure differently now.
    await page.evaluate(() => (window as any).__docView.relayout());
    await page.waitForFunction(() => (window as any).__docView.layoutDone === true, undefined, { timeout: 60_000 });
    await settled(page);
    await expect.poll(async () => (await state()).layouts, { message: 'the chart is laid out again after relayout()' }).toBe(2);
    expectColumns(await onPage(page, GREEN));

    // An entry that came into the font table (a paste brings one): the next edit lays everything out again, the charts too.
    await page.goto('/e2e/pages/doc-edit.html');
    await expect(page.locator('#state')).toHaveText('ready');
    await page.evaluate(([input]) => (window as any).__mountEdit(input, {}), [Array.from(await chartDoc())]);
    await page.waitForFunction(() => (window as any).__view.layoutDone === true, undefined, { timeout: 60_000 });
    await settled(page);
    const edited = () => page.evaluate(() => (window as any).__view.getChartState() as { layouts: number });
    await expect.poll(async () => (await edited()).layouts).toBe(1);
    await page.evaluate(() => {
      const view = (window as any).__view;
      view.setSelection({ story: 'body', path: [1], offset: 0 });
      view.insertText('a');
    });
    await settled(page);
    expect((await edited()).layouts, 'an edit of the text lays no chart out again').toBe(1);
    await page.evaluate(() => {
      const view = (window as any).__view;
      view.document.fonts.set('Another Face', { name: 'Another Face' });
      view.insertText('b');
    });
    await settled(page);
    await expect.poll(async () => (await edited()).layouts, { message: 'the chart is laid out again after the font table changed' }).toBe(2);
  });

  test('the printed page holds the chart, at the resolution of the printer', async ({ page }) => {
    const frame = await frameOnPage(page);
    await mountDoc(page, await chartDoc());
    const screen = await onPage(page, GREEN);
    await page.evaluate(() => {
      const w = window as any;
      w.__prints = 0;
      // No real print dialog: what would be printed is looked at when print() of the window is called.
      window.print = () => void w.__prints++;
      w.__printed = undefined;
      w.__docView.print({ dpi: 200 }).then(
        (result: unknown) => (w.__printed = { result }),
        (error: any) => (w.__printed = { error: String(error && error.message) }),
      );
    });
    await expect.poll(() => page.evaluate(() => (window as any).__prints), { timeout: 60_000, message: 'print() of the window is called' }).toBe(1);
    const printed = await page.evaluate(findColour, { source: 'print' as const, index: 0, colour: GREEN, pageWidth: 600 });
    await page.evaluate(() => void window.dispatchEvent(new Event('afterprint')));
    await expect.poll(() => page.evaluate(() => (window as any).__printed), { timeout: 60_000 }).toBeTruthy();
    expect(await page.evaluate(() => (window as any).__printed.error)).toBeUndefined();
    // 200 dots per inch: 200 / 96 pixels per px of the page.
    expect(printed.scale).toBeGreaterThan(2);
    expect(printed.scale).toBeLessThan(2.2);
    expectInFrame(printed, frame);
    expectColumns(printed);
    // More pixels than the screen has for it, unless the screen is as fine as the printer.
    if (screen.scale < 2) expect(printed.count).toBeGreaterThan(screen.count);
    expect(await page.evaluate(() => document.querySelectorAll('.bym-print').length), 'the print job is taken out of the document').toBe(0);
  });

  test('a chart part that cannot be read leaves a placeholder; the document is shown', async ({ page }) => {
    await frameOnPage(page);
    expect((await onPage(page, GREEN)).count).toBe(0);
    const grey = await onPage(page, PLACEHOLDER);
    expect(grey.count, 'the placeholder fills the frame').toBeGreaterThan(FRAME.width * FRAME.height * 0.8 * grey.scale * grey.scale);
    const text = await page.evaluate(async () => {
      const doc = await (window as any).__docFile.document();
      return { warnings: doc.warnings as string[], paragraphs: doc.body.blocks.length as number };
    });
    expect(text.paragraphs).toBe(2);
    expect(text.warnings.some((line) => /chart1\.xml.*could not be read/.test(line))).toBe(true);
    await expectResponsive(page);
  });

  test('saving gives the bytes of the file, and an edit leaves the chart parts as they were', async ({ page }) => {
    const bytes = await chartDoc();
    await mountDoc(page, bytes);
    const same = await page.evaluate(async (input) => {
      const saved: Uint8Array = await (window as any).__docFile.save();
      return saved.length === input.length && saved.every((value, i) => value === input[i]);
    }, Array.from(bytes));
    expect(same, 'open, show, save: the bytes of the file').toBe(true);

    await page.goto('/e2e/pages/doc-edit.html');
    await expect(page.locator('#state')).toHaveText('ready');
    await page.evaluate(([input]) => (window as any).__mountEdit(input, {}), [Array.from(bytes)]);
    await page.waitForFunction(() => (window as any).__view.layoutDone === true, undefined, { timeout: 60_000 });
    const saved = await page.evaluate(async () => {
      const w = window as any;
      const view = w.__view;
      // After the last character of the document: the paragraph below the chart.
      view.setSelection({ anchor: { story: 'body', path: [1], offset: 15 }, focus: { story: 'body', path: [1], offset: 15 } });
      view.insertText(' and more');
      return Array.from((await w.__mounted.save()) as Uint8Array);
    });
    const before = ZipArchive.read(bytes);
    const after = ZipArchive.read(new Uint8Array(saved));
    expect(after.names().sort()).toEqual(before.names().sort());
    for (const name of ['word/charts/chart1.xml', 'word/charts/_rels/chart1.xml.rels', 'word/embeddings/Microsoft_Excel_Sheet1.xlsx', 'word/_rels/document.xml.rels']) {
      expect(Array.from(after.entry(name)!.raw as Uint8Array), name).toEqual(Array.from(before.entry(name)!.raw as Uint8Array));
    }
    const text = new TextDecoder().decode(await after.read('word/document.xml'));
    expect(text).toContain('Below the chart and more');
    expect(text).toContain('<c:chart ');
    // The edited document still shows the chart.
    await settled(page);
    expectColumns(await onPage(page, GREEN));
  });
});
